type Attempt struct{Trace string `json:"trace"`;DNS []string `json:"dns"`;Local string `json:"local"`;Peer string `json:"peer"`;Status int `json:"status"`;Error string `json:"error"`}
type Outcome struct{OK bool `json:"ok"`;Reason string `json:"reason"`;Attempts []Attempt `json:"attempts"`;Body json.RawMessage `json:"body,omitempty"`}
func ReadExport(in Input) Outcome{
 out:=Outcome{Attempts:[]Attempt{}}
 if in.Method!="GET"{out.Reason="readonly method";return out}
 p:=in.Policy
 if p.MaxAttempts<1||p.MaxAttempts>4||p.AttemptMS<1||p.AttemptMS>500||p.OverallMS<1||p.OverallMS>2500||p.BackoffMS<0||p.BackoffMS>100{out.Reason="unapproved retry budget";return out}
 root,e:=os.ReadFile(in.CAFile);if e!=nil{out.Reason=e.Error();return out};pool:=x509.NewCertPool();if !pool.AppendCertsFromPEM(root){out.Reason="invalid CA";return out}
 cert,e:=tls.LoadX509KeyPair(in.ClientCert,in.ClientKey);if e!=nil{out.Reason=e.Error();return out}
 ctx,cancel:=context.WithTimeout(context.Background(),time.Duration(p.OverallMS)*time.Millisecond);defer cancel()
 resolver:=&net.Resolver{PreferGo:true,Dial:func(c context.Context,network,address string)(net.Conn,error){return (&net.Dialer{}).DialContext(c,"udp",net.JoinHostPort("127.0.0.1",strconv.Itoa(in.DNSPort)))}}
 for index:=0;index<p.MaxAttempts;index++{
  if ctx.Err()!=nil{break};c,done:=context.WithTimeout(ctx,time.Duration(p.AttemptMS)*time.Millisecond);b:=make([]byte,16);_,_=rand.Read(b);a:=Attempt{Trace:hex.EncodeToString(b),DNS:[]string{}}
  transport:=&http.Transport{TLSClientConfig:&tls.Config{RootCAs:pool,Certificates:[]tls.Certificate{cert},ServerName:in.Target.SNI,MinVersion:tls.VersionTLS12},DisableKeepAlives:true,DialContext:func(dc context.Context,network,address string)(net.Conn,error){ips,err:=resolver.LookupIP(dc,"ip4",in.Target.Host);if err!=nil{return nil,err};for _,ip:=range ips{a.DNS=append(a.DNS,ip.String())};if len(ips)==0{return nil,fmt.Errorf("no exported address")};conn,err:=(&net.Dialer{}).DialContext(dc,"tcp",net.JoinHostPort(ips[0].String(),strconv.Itoa(in.Target.Port)));if conn!=nil{a.Local=conn.LocalAddr().String();a.Peer=conn.RemoteAddr().String()};return conn,err}}
  req,err:=http.NewRequestWithContext(c,"GET","https://"+net.JoinHostPort(in.Target.Host,strconv.Itoa(in.Target.Port))+"/snapshot?trace="+a.Trace,nil)
  if err!=nil{transport.CloseIdleConnections();done();out.Reason=err.Error();return out};req.Header.Set("X-Request-Id",a.Trace)
  req=req.WithContext(httptrace.WithClientTrace(req.Context(),&httptrace.ClientTrace{GotConn:func(info httptrace.GotConnInfo){a.Local=info.Conn.LocalAddr().String();a.Peer=info.Conn.RemoteAddr().String()}}))
  resp,err:=(&http.Client{Transport:transport,CheckRedirect:func(_ *http.Request,_ []*http.Request)error{return http.ErrUseLastResponse}}).Do(req)
  var body []byte
  if err==nil{a.Status=resp.StatusCode;body,err=io.ReadAll(io.LimitReader(resp.Body,65536));resp.Body.Close()};if err!=nil{a.Error=err.Error()};transport.CloseIdleConnections();done();out.Attempts=append(out.Attempts,a)
  if err==nil&&a.Status==200{var document struct{DataSHA string `json:"data_sha256"`;Data struct{Version string `json:"dataset_version"`} `json:"data"`};if json.Unmarshal(body,&document)==nil&&document.DataSHA==in.Target.ExpectedSHA&&document.Data.Version==in.Target.Version{out.OK=true;out.Body=body;return out};out.Reason="immutable version mismatch";return out}
  if a.Status>=400&&a.Status<500{out.Reason="export route refused";return out}
  if index+1<p.MaxAttempts{timer:=time.NewTimer(time.Duration(p.BackoffMS)*time.Millisecond);select{case <-ctx.Done():if !timer.Stop(){<-timer.C};case <-timer.C:}}
 }
 out.Reason="bounded export unavailable";return out
}
原题：使用可跨域路由的受控入口，统一身份与TLS并区分本地和远端健康；明确地址重叠、DNS和流量策略。演练单集群断连和部分恢复，要求无循环转发、重试预算有界，关键业务是否允许跨域由一致性约束决定。

